// Auto-generated Turkish Geodetic & Mining Legislation Dataset
window.LEGISLATION_DATA = {
  "mapeg": "<div class=\"legislation-doc-container\">\n  <div class=\"legislation-doc-header\">\n    <div class=\"d-flex items-center gap-6 mb-2\">\n      <span class=\"badge badge-amber font-mono\">T.C. ENERJİ VE TABİİ KAYNAKLAR BAKANLIĞI</span>\n      <span class=\"badge badge-emerald font-mono\">YÜRÜRLÜK: 01.05.2025</span>\n    </div>\n    <h2 class=\"legislation-doc-title\">MADEN VE PETROL İŞLERİ GENEL MÜDÜRLÜĞÜNE SUNULACAK HÂLİHAZIR HARİTA VE İMALAT HARİTALARININ ÜRETİMİNE İLİŞKİN YÖNERGE</h2>\n    <div class=\"legislation-meta-bar\">\n      <span><i class=\"fa-solid fa-file-word text-amber\"></i> Orijinal Dosya: MapegHaritaveimalatYonerge_4.11.2025.docx</span>\n      <span><i class=\"fa-solid fa-building-columns text-cyan\"></i> MAPEG Harita ve İmalat Dairesi</span>\n    </div>\n  </div>\n  <div class=\"legislation-doc-body\"><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Amaç</h3><div class=\"legislation-article-card\" id=\"mapeg-art-2\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 1- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 1- (1) Bu Yönergenin amacı, yersel veya fotogrametrik yöntemler ile üretilerek, Maden ve Petrol İşleri Genel Müdürlüğüne sunulan hâlihazır harita ile imalat haritası bilgilerinin üretimine ilişkin usul ve esasları belirlemektir.', 'MADDE 1- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönergenin amacı, yersel veya fotogrametrik yöntemler ile üretilerek, Maden ve Petrol İşleri Genel Müdürlüğüne sunulan hâlihazır harita ile imalat haritası bilgilerinin üretimine ilişkin usul ve esasları belirlemektir.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Kapsam</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-4\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 2- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 2- (1) Bu Yönerge; hâlihazır harita ile imalat haritası ve harita bilgilerinin üretilmesine, derlenmesine, analiz edilmesine, görselleştirilmesine, saklanmasına ve araziye uygulanmasına ilişkin teknik esasları kapsar.', 'MADDE 2- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönerge; hâlihazır harita ile imalat haritası ve harita bilgilerinin üretilmesine, derlenmesine, analiz edilmesine, görselleştirilmesine, saklanmasına ve araziye uygulanmasına ilişkin teknik esasları kapsar.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Dayanak</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-6\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 3- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 3- (1) Bu Yönerge 11.12.2022 tarihli ve 32040 sayılı Resmî Gazete’de yayımlanan Maden Yönetmeliğine dayalı olarak hazırlanmıştır.', 'MADDE 3- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönerge 11.12.2022 tarihli ve 32040 sayılı Resmî Gazete’de yayımlanan Maden Yönetmeliğine dayalı olarak hazırlanmıştır.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Tanımlar ve kısaltmalar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-8\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 4- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 4- (1) Bu Yönergede geçen;', 'MADDE 4- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönergede geçen;</p><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">BDN (Bağımsız Denetleme Noktası):</span>\n      <span class=\"def-desc text-muted\">Yeryüzünde tesis edilen, koordinatları ve yüksekliği bu Yönergede belirlenen yöntemlerle oluşturulan ve veri işleme aşamasında dengelemeye tabi tutulmayan noktayı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">BN:</span>\n      <span class=\"def-desc text-muted\">Bakılan Noktayı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">DN:</span>\n      <span class=\"def-desc text-muted\">Durulan Noktayı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">ED50 (Avrupa Datumu-1950):</span>\n      <span class=\"def-desc text-muted\">Hayford elipsoidine (a= 6378388.0 m, f=1/297.0) dayalı datumu,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">Genel Müdürlük:</span>\n      <span class=\"def-desc text-muted\">Maden ve Petrol İşleri Genel Müdürlüğünü,</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">GNSS (Global Navigation Satellite Systems): Küresel Seyrüsefer Uydu Sistemlerini,</p><p class=\"legislation-p leading-relaxed text-muted\">GZK: Gerçek Zamanlı Kinematiği,</p><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">Hâlihazır harita:</span>\n      <span class=\"def-desc text-muted\">Ruhsat veya hammadde üretim izin sahasında, mevcut topoğrafik durumunun ve yol, bina, şev gibi diğer detayların gösterildiği, koordinat ve yükseklik bilgilerini içeren 1:2.000, 1:1.000, 1:500 veya daha büyük ölçekteki sayısal haritayı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">ITRF (International Terrestrial Reference Frame):</span>\n      <span class=\"def-desc text-muted\">Uluslararası Yersel Referans Çerçevesini,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">ITRF96:</span>\n      <span class=\"def-desc text-muted\">1996 yılında güncellenmiş ITRF’yi,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">İHA (İnsansız Hava Aracı):</span>\n      <span class=\"def-desc text-muted\">Üzerinde pilot bulunmaksızın, uzaktan İHA pilotu tarafından kumanda edilen veya otonom uçuş yapabilen hava aracını,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">İHA0:</span>\n      <span class=\"def-desc text-muted\">Azami kalkış ağırlığı 500 gr (dâhil) - 4 kg aralığında olan İHA'yı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">İmalat haritası:</span>\n      <span class=\"def-desc text-muted\">Ruhsat veya hammadde üretim izin sahasında; maden üretimi yapılan ve yapılması planlanan ocak alanları ile stok, pasa, liç, atık, artık ve benzeri alanların gösterildiği, koordinat ve yükseklik bilgilerini içeren 1:2.000, 1:1.000, 1:500 veya daha büyük ölçekteki sayısal haritayı,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">Ortofoto:</span>\n      <span class=\"def-desc text-muted\">Eğiklik, dönüklük gibi etkilerden arındırılmış hava fotoğraflarını,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">PPK (Post-Processed Kinematic):</span>\n      <span class=\"def-desc text-muted\">Ölçüm Sonrası Kinematik değerlendirmeyi,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">RTK (Real-Time Kinematic):</span>\n      <span class=\"def-desc text-muted\">Gerçek Zamanlı Kinematik değerlendirmeyi,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">SHGM:</span>\n      <span class=\"def-desc text-muted\">Sivil Havacılık Genel Müdürlüğünü,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">SYM (Sayısal Yüzey Modeli):</span>\n      <span class=\"def-desc text-muted\">İnsan yapısı detaylar ve bitki örtüsü dâhil arazi yüzeyini temsil eden, çoğunlukla karesel düzenli bir grid yapıda veya düzensiz üçgensel formdaki yükseklik verisini,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">TKGM:</span>\n      <span class=\"def-desc text-muted\">Tapu ve Kadastro Genel Müdürlüğünü,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">TM:</span>\n      <span class=\"def-desc text-muted\">Transversal Mercator projeksiyonunu,</span>\n    </div><div class=\"legislation-def-row\">\n      <span class=\"def-term text-amber font-mono font-bold\">TUSAGA-Aktif:</span>\n      <span class=\"def-desc text-muted\">Türkiye Ulusal Sabit GNSS Ağı-Aktif (GZK hizmeti veren GNSS Ağı),</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">UTM: Universal Transversal Mercator projeksiyonunu,</p><p class=\"legislation-p leading-relaxed text-muted\">YDE: Yatay Açı/Düşey Açı/Eğik Mesafeyi,</p><p class=\"legislation-p leading-relaxed text-muted\">YKN (Yer Kontrol Noktası): Yeryüzünde tesis edilen, koordinatları ve yüksekliği bu Yönergede belirlenen yöntemlerle oluşturulan ve veri işleme aşamasında dengelemeye tabi tutulan noktayı,</p><p class=\"legislation-p leading-relaxed text-muted\">YMK: Yatay Mesafe/Kot farkını,</p><p class=\"legislation-p leading-relaxed text-muted\">YÖA: Sayısal hava fotoğrafındaki bir pikselin yeryüzü üzerindeki karşılığını,</p><p class=\"legislation-p leading-relaxed text-muted\">ifade eder.</p><p class=\"legislation-p leading-relaxed text-muted\">Haritalarda kullanılacak projeksiyon, datum ve yükseklik sistemleri</p></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-37\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 5- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 5- (1) Genel Müdürlüğe ibraz edilen hâlihazır harita ve imalat haritaları, UTM Projeksiyon ED 50 Datum (6 derecelik) ve TM Projeksiyon ITRF 96 Datum (3 derecelik) sistemlerinde ve sayısal formatta olmalıdır.', 'MADDE 5- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Genel Müdürlüğe ibraz edilen hâlihazır harita ve imalat haritaları, UTM Projeksiyon ED 50 Datum (6 derecelik) ve TM Projeksiyon ITRF 96 Datum (3 derecelik) sistemlerinde ve sayısal formatta olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Haritalarda projeksiyon ve datum bilgileri tanımlanmış olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) Genel Müdürlük, gerekli gördüğü takdirde başka bir projeksiyon ve datum sistemi kullanabilir.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) Noktaların yükseklik değerleri Ortometrik (H=h-N) sistemde olmalıdır. Noktaların Elipsoit Yüksekliklerinin (h), Helmert Ortometrik Yükseklik (H) sistemine dönüşümü için gerekli hesaplama, Harita Genel Müdürlüğü tarafından https://www.harita.gov.tr/ adresinde yayımlanan “Standart Paftalar İçin Datum Kayıklık Değerleri” kullanılarak yapılmalıdır. Ruhsat sahası hangi 1:25.000 ölçekli pafta sınırı içerisinde kalıyor ise o pafta numarasına göre elde edilen değer (N) ondülasyon değeri olarak kullanılmalıdır. Ruhsat alanının birden fazla 1:25.000 ölçekli pafta sınırı içerisinde kalması durumunda ise her bir paftanın (N) ondülasyon değeri bulunarak bu değerlerin aritmetik ortalaması alınmalı ve elde edilen değer (N) ondülasyon değeri olarak kullanılmalıdır. (Örn. J50a1 paftası için ondülasyon değerinin 25,45 m, J50a2 paftası için ondülasyon değerinin 25,49 m ve J50a3 paftası için ondülasyon değerinin 25,36 m olduğu kabul edilirse her üç paftayı kapsayan ruhsat sahası için kullanılacak (N) ondülasyon değeri (25,45+25,49+25,36)/3=25,43 m olarak alınmalıdır.)</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Poligon noktaları ile YKN ve BDN’lerin tesisinde uyulacak esaslar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-42\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 6- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 6- (1) Ölçüme esas teşkil eden poligon noktaları, birbirini görecek ve en az 3 adet olacak şekilde tesis edilmelidir. Tesis edilecek her bir poligon noktası arasındaki mesafe en az 30 m olmalıdır. Bu noktalar tesis edilirken, ocak açılması planlanan bölgede ve ocak ilerleme yönünde olmamasına dikkat edilmeli, varsa yerli kaya, bina köşesi gibi yüzeylere kaybolmayacak şekilde tesis edilmelidir. Zeminde bahsi geçen şekilde sabit nokta tesis edilemiyorsa poligon betonu, çivisi veya boru kullanılarak bu standart mutlaka sağlanmalıdır. Tesisi yapılan her bir poligon noktası en az 3 noktadan röperlenmelidir.', 'MADDE 6- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Ölçüme esas teşkil eden poligon noktaları, birbirini görecek ve en az 3 adet olacak şekilde tesis edilmelidir. Tesis edilecek her bir poligon noktası arasındaki mesafe en az 30 m olmalıdır. Bu noktalar tesis edilirken, ocak açılması planlanan bölgede ve ocak ilerleme yönünde olmamasına dikkat edilmeli, varsa yerli kaya, bina köşesi gibi yüzeylere kaybolmayacak şekilde tesis edilmelidir. Zeminde bahsi geçen şekilde sabit nokta tesis edilemiyorsa poligon betonu, çivisi veya boru kullanılarak bu standart mutlaka sağlanmalıdır. Tesisi yapılan her bir poligon noktası en az 3 noktadan röperlenmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) GNSS tekniği ile poligon, YKN ve BDN gibi sabit noktaların konumları; statik, hızlı statik, kinematik veya gerçek zamanlı kinematik yöntemlerinden herhangi birisi ile belirlenebilir.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">Statik ve hızlı statik gözlemlerde;</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">1) Uydu sayısı: En az 5 adet,</p><p class=\"legislation-p leading-relaxed text-muted\">2) Uydu yükseklik açısı: 10°,</p><p class=\"legislation-p leading-relaxed text-muted\">3) Veri toplama aralığı: 10 saniye veya daha az,</p><p class=\"legislation-p leading-relaxed text-muted\">4) Baz uzunluğu: En fazla 5 km,</p><p class=\"legislation-p leading-relaxed text-muted\">5) Ölçüm Süresi: En az 10 dakika,</p><p class=\"legislation-p leading-relaxed text-muted\">alınır. Ölçümler, en az iki referans noktasına dayalı yapılmalıdır. Hesaplanan noktanın konum doğruluğu yatayda ve düşeyde ± 8 cm (dâhil)’den daha iyi olmalıdır.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">Ölçüm sonrası veya ölçüm esnasında poligon, YKN ve BDN gibi sabit noktalarının konumları kinematik yöntemlerle belirlenebilir. Her sabit nokta, aşağıdaki koşulları sağlayacak şekilde ve farklı zamanlarda en az iki oturum GNSS ölçümü yapılarak tesis edilir. İki oturumdan elde edilen iz düşüm koordinatları ve elipsoit yükseklikleri arasındaki farklar ±7 cm (dâhil)’den fazla olamaz. Kinematik yöntemlerde;</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">1) Uydu sayısı: En az 5 adet,</p><p class=\"legislation-p leading-relaxed text-muted\">2) Uydu yükseklik açısı: 10°,</p><p class=\"legislation-p leading-relaxed text-muted\">3) Veri toplama aralığı: 5 saniye veya daha az,</p><p class=\"legislation-p leading-relaxed text-muted\">4) Referans noktasına uzaklık: En fazla 5 km,</p><p class=\"legislation-p leading-relaxed text-muted\">5) Ölçüm süresi: Her noktada en az 10 epok,</p><p class=\"legislation-p leading-relaxed text-muted\">6) Oturumlar arası zaman: En az bir saat,</p><p class=\"legislation-p leading-relaxed text-muted\">alınır.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">Sabit noktaların koordinatları; TUSAGA-Aktif sisteminde Ağ GZK yöntemiyle de belirlenebilir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">TUSAGA-Aktif sisteminde sabit noktaların koordinatları; (d) bendinde belirtilen koşulları sağlayacak şekilde ve farklı zamanlarda en az iki GNSS oturumu ile belirlenir. İki oturumdan elde edilen iz düşüm koordinatları ve elipsoit yükseklikleri arasındaki farklar ±7cm (dâhil)’den küçük olmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">d)</span>\n      <span class=\"clause-text text-muted\">TUSAGA-Aktif Sisteminde Ağ GZK Yönteminde;</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">1) Düzeltme verileri alınırken kullanılabilecek teknik: VRS, FKP veya MAC,</p><p class=\"legislation-p leading-relaxed text-muted\">2) İlk faz başlangıç belirsizliği çözümü: Sabitlenmiş,</p><p class=\"legislation-p leading-relaxed text-muted\">3) Uydu sayısı: En az 5 adet,</p><p class=\"legislation-p leading-relaxed text-muted\">4) Uydu yükseklik açısı: 10°,</p><p class=\"legislation-p leading-relaxed text-muted\">5) Veri toplama aralığı: Bir saniye,</p><p class=\"legislation-p leading-relaxed text-muted\">6) Ölçüm süresi: Her noktada en az 10 epok,</p><p class=\"legislation-p leading-relaxed text-muted\">7) Oturumlar arası zaman: En az bir saat,</p><p class=\"legislation-p leading-relaxed text-muted\">alınır.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) En az birer saat ara ile iki oturum şeklinde tesis edilen sabit noktalara ait veriler aynı iş dosyası içerisinde olmalı ve ayrıca RTK/GNSS ve TUSAGA-Aktif/GNSS yöntemleri ile tesis edilen sabit noktalara ait iş dosyaları ayrı ayrı oluşturulmalıdır.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Ölçüm ve haritalamaya ilişkin genel esaslar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-72\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 7- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 7- (1) Yersel yöntemlerle yapılacak ölçüm işlemleri, ölçme doğruluğu ±(7 mm+7 ppm) (dâhil)’den daha yüksek doğruluklu elektronik uzunluk ölçerlerle yapılmalı, bu ölçümlerde alet ve işaret yükseklikleri cm duyarlığında belirlenmelidir. Doğrultular, yatay açı ölçme doğruluğu 7″ (dâhil)’den daha yüksek cihazlarla ölçülmelidir.', 'MADDE 7- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Yersel yöntemlerle yapılacak ölçüm işlemleri, ölçme doğruluğu ±(7 mm+7 ppm) (dâhil)’den daha yüksek doğruluklu elektronik uzunluk ölçerlerle yapılmalı, bu ölçümlerde alet ve işaret yükseklikleri cm duyarlığında belirlenmelidir. Doğrultular, yatay açı ölçme doğruluğu 7″ (dâhil)’den daha yüksek cihazlarla ölçülmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Elektronik uzunluk ölçerler ile yapılacak ölçümde kullanılan (DN/BN noktalar) poligon noktalarının isimleri, GNSS tekniği ile tesis edilen poligon noktalarının isimleri ile aynı olmalıdır. (Örn: GNSS ile tesis edilen poligon noktası isimleri P.1, P.2 ise Durulan Nokta P.1, Bakılan Nokta P.2 olarak seçilmelidir.)</p><p class=\"legislation-p leading-relaxed text-muted\">(3) Yersel ölçüm işlemine başlamadan önce, istasyon noktası ile çıkış alınan/bağlanılan noktaya kontrol okuması yapılmalıdır. Durulan Nokta (DN) ve/veya Bakılan Nokta (BN) değiştiği takdirde de kontrol okuması yapılmalıdır. Yapılan kontrol okumasında okunan noktalar sırası ile 1_KNT, 2_KNT… olacak şekilde sıralı isimlendirilmelidir. Yapılan okuma sonucu koordinat değerleri arasındaki fark ±5 cm’yi, kot değerleri arasındaki fark ise ±7 cm’yi geçmemelidir. Geriden veya ileriden kestirme yönteminde de kontrol okuması zorunlu olup hata miktarı belirtilen bu değerleri geçmemelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) TUSAGA-Aktif/GNSS yöntemi ile detay alımı yapılması hâlinde her bir detay noktasında en az 3 epok okuma yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(5) RTK/GNSS yöntemi ile sabit nokta tesis edilmesi hâlinde her bir sabit noktada en az 3 epok, detay alım yapılması hâlinde ise her bir detay noktasında en az 1 epok okuma yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(6) Detay alımı yapılırken, haritası üretilecek bölgedeki; ocak, pasa, liç ve stok gibi detaylara ait şev altı, şev üstü ve şev yüzeylerini temsil edecek sıklıkta nokta okuması yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(7) Şevli yüzeylerde, şev hattı ve şev yüzeyi ara okumaları 20 m’yi geçmeyecek şekilde yapılmalı ve alımı yapılan noktaların koordinat ve kotları cm hassasiyetinde olmalıdır. Bu noktalar, şev kırıkları ile karakteristik noktaları temsil etmeli ve düz hatlarda iki nokta arasındaki mesafe 20 m’yi geçmemelidir. Söz konusu noktalar esas alınarak oluşturulan üçgen modeldeki üçgenin kenarları 30 m’yi geçmemelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(8) Alanın topoğrafik durumunun belirlenebilmesi için gereken desen ve karakteristik noktalar ölçülmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(9) Arazideki; yollar, dere yatakları, enerji nakil hatları, bina, tesis, şev vb. ile arazi eğiminin fazla olduğu ve/veya sık değiştiği bölümler için yeterli yoğunlukta detay alımı yapılmalı ve söz konusu detaylar harita üzerinde gösterilmelidir. Alımı yapılan detay noktaları arasındaki mesafe 20 m’yi geçmemelidir. Söz konusu noktalar esas alınarak oluşturulacak üçgen modeldeki üçgenin kenarları da 30 m’yi geçmemelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(10) Ocak sahasındaki şevli yüzeylerden, üretim faaliyetine yönelik olmayan (yol şevi vb.) kısımlara harita üzerinde gerekli açıklama yazılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(11) Delme-çatlatma, elmas telle kesme ve zincirli kollu kesicilerle kesme gibi yöntemler kullanılarak blok üretimi yapılan ocak alanlarında yapılan ölçümlerde şev üstü ve şev altı noktaları, karakteristik noktalar ile diğer tüm detay noktaların alımı yapılmalı ve bu noktalar ocak geometrisini yansıtmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(12) On birinci fıkrada belirtilen hususun; ters şev ve/veya şev önü pasa yığını gibi kısıtlayıcı faktörlerden ötürü sağlanamadığı durumlarda ve ayrıca ölçüm ve çizim yöntemine bağlı olarak oluşan zorunlu hâllerde şev altı hattını temsil eden noktalarda kısmi öteleme yapılabilir. Öteleme yapılması durumunda, bu noktalar hem orijinal hâli ile ve hem de öteleme yapılmış hâli ile haritada gösterilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(13) İşletme faaliyet raporu ekinde verilecek olan imalat haritalarında, ocak ilerleme yönüne bağlı olarak, muhtemel çalışma alanlarını içerisine alacak ve ocak çalışma alanı sınırından en az 50 m mesafeyi kapsayacak şekilde ocak alanı sınırının dışında kalan bölge için de detay alımı yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(14) İşletme izni ve izin alanı genişletme taleplerinde, temdit talepli projelerde veya mevcut işletme izin alanı içerisinde farklı bir lokasyonda ocak açılmasının planlanması durumlarında hâlihazır haritası oluşturulan alan, termin planı yapılan alandan daha küçük olmamalıdır. Termin planı yapılan alanın 10 hektardan daha küçük olması hâlinde ise termin planı yapılan alanı kapsayacak ve 10 hektardan az olmayacak şekilde hâlihazır harita oluşturulmalıdır. Üretim faaliyetleri devam eden sahalardaki ölçüm işlemi, haritanın Genel Müdürlüğe ibraz edildiği tarihten önceki en fazla 1 (bir) aylık zaman aralığında yapılmış olmalıdır. Yer altı üretim yöntemi ile çalışma yapılacak sahalar için, ocak ağzı ve nefeslik gibi yer üstü ile bağlantısı olan alanlar için 1 hektardan az olmamak üzere ve ayrıca pasa, stok, karot sahası ve geçici tesis alanları için hâlihazır harita oluşturulmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(15) On dördüncü fıkra kapsamında haritası oluşturulacak bölgenin kar örtüsü ile kaplı olması veya sık ağaçlık, ormanlık, çalılık olması nedeni ile harita oluşturmaya engel durum bulunması hâlinde bu Yönerge ekinde yayımlanan taahhütnameler ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(16) Hammadde üretim izin taleplerinde, talep alanının tamamı için hâlihazır harita oluşturulmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(17) İşletme izin taleplerinde, hammadde üretim izin taleplerinde veya temdit talepli projelerde, ruhsat alanında önceki dönemlerde çalışılmış ocak var ise mevcut ocak alanlarına ait imalat haritası ile on dördüncü fıkra kapsamında oluşturulan hâlihazır harita ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(18) Haritada gösterilen; nokta, çizgi, alan, yazı ve semboller öznitelik verisine ve bu Yönerge ekinde yayımlanan tabaka yapısına uygun şekilde oluşturulmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(19) Genel Müdürlüğe, işletme faaliyet raporu ekinde verilecek imalat haritaları ile ilgili olarak 4/6/1985 tarihli ve 3213 sayılı Maden Kanunu ve ilgili yönetmeliklerdeki hükümler saklı kalmak kaydı ile aşağıda belirlenen esaslar geçerlidir.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">Ocak sahasının imalat ölçümünün, ait olduğu takvim yılı kapandıktan sonra yapılması esastır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">Takvim yılı kapanmadan, sahada üretim faaliyetlerinin sonlandırılması ya da yıl sonuna kadar ara verilmesi hâlinde takvim yılının kapanması beklenmeden ölçüm yapılabilir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">(a) bendinde belirtilen şartın kar muhalefeti nedeni ile sağlanamaması hâlinde, 1 Kasım tarihinden önce olmamak kaydı ile ocak sahasının ölçümü yapılabilir. Bu durumda, ölçüm yapıldıktan sonra sahada üretim faaliyetlerinin devam etmesi hâlinde, ölçümün yapıldığı tarih ile takvim yılı sonuna kadar sahadan yapılan üretim miktarı, işletme faaliyet raporunun “Üretim Bilgileri Açıklaması” bölümünde ve imalat haritası üzerinde açıklama olarak yazılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">Bir sonraki takvim yılında ölçüm yapılması hâlinde takvim yılının başladığı tarihten itibaren ölçümün yapıldığı tarihe kadar geçen süre içerisinde sahadan yapılan üretim miktarı, işletme faaliyet raporunun “Üretim Bilgileri Açıklaması” bölümünde ve imalat haritası üzerinde açıklama olarak yazılmalıdır.</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">(20) Ölçüme ait sayısal harita, ham data verisi, uçuşa ait fotoğraflar vb. veriler en az 5 (beş) yıl süre ile muhafaza edilmeli ve Genel Müdürlükçe istenmesi hâlinde ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(21) Genel Müdürlük gerekli gördüğü takdirde ölçüm cihazlarına ait kalibrasyon raporlarının ibrazını isteyebilir.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Yer altı ölçümlerinde uyulacak esaslar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-98\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 8- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 8- (1) Beşinci, altıncı ve yedinci maddelerde belirlenen genele şamil esaslar, yer altı ölçüm yöntemi için de geçerlidir. Bunun yanında, yer altı ocak ölçümlerinde aşağıdaki hususlara uyulması gerekmektedir.', 'MADDE 8- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Beşinci, altıncı ve yedinci maddelerde belirlenen genele şamil esaslar, yer altı ölçüm yöntemi için de geçerlidir. Bunun yanında, yer altı ocak ölçümlerinde aşağıdaki hususlara uyulması gerekmektedir.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">Ocak içerisindeki ana ve ara poligonlar; tavana veya galeri yan yüzeylerine, sağlam kayaç üzerine kalıcı olacak şekilde tesis edilmelidir. Noktaların tesis edileceği zemin ve tahkimat yüzeyinin sağlam olması gereklidir. Bu noktalar, desandri/galeri yan yüzeyine ve/veya tavana, madencilik faaliyetlerinden etkilenmeyecek, deforme olmayacak ve kaybolmayacak şekilde tesis edilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">Poligon noktaları, yer altı işletme şekillerine göre; ana ve ara poligonlar şeklinde tesis edilmeli, ölçüm işlemi de yer altı açıklıkları boyunca tesis edilen ana veya ara poligon dizileri yardımıyla yapılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">Elektronik uzunluk ölçer veya teodolit ile ölçüm yapılamayan durumlarda asma pusula ölçüsü yapılmalıdır. Asma pusula ile ölçüm yapılması hâlinde, gerçek kuzey ile manyetik kuzey arasındaki sapma değeri (İSA) pusula ölçü karnesine yazılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">Pusula ölçüleri, demir cevherinde ve demir/çelik tahkimatlı alanlarda yapılmamalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">d)</span>\n      <span class=\"clause-text text-muted\">Ana poligonlar; yer altında ana nakil yolları, havalandırma yolları/boşlukları ve ana galeriler gibi alanlarda tesis edilmelidir. Ara poligonlar ise ana poligon noktalarını sıklaştırmada, detay alımında, küçük galeri ve yer altı boşluklarının ölçümünde ve bu alanlardaki değişimlerin belirlenmesinde, üretim alanlarında işletmenin sürekli değişen durumunun ortaya konması için ayaklarda ve panolarda oluşturulan ve tavan/taban yolları boyunca tesis edilen poligon dizilerinden oluşmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">e)</span>\n      <span class=\"clause-text text-muted\">Tesis edilen poligon noktaları arasındaki mesafe mümkün olduğunca uzun tutulmalı ve noktaların tesis edildiği yüzeyin (taban, tavan, galeri yan yüzeyi) kotları kullanılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">f)</span>\n      <span class=\"clause-text text-muted\">Ana ve ara poligon geçkileri, yeryüzünden bağlantı ölçümleri ile kontrollü şekilde oluşturulmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">g)</span>\n      <span class=\"clause-text text-muted\">Yüzeyde tesis edilecek poligon noktalarının tesisinde, bu Yönergede belirlenen konum ve yükseklik doğrulukları ile ölçüm esaslarına uyulmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ğ)</span>\n      <span class=\"clause-text text-muted\">İmalat alanları, panolar, yıl bazında çalışma alanları, cevher kalınlığı, cevher eğimi ve dalım yönü, cevher isimleri, taban kotları, günlük/haftalık/aylık bazda ölçüm yapılması durumunda ölçüm tarihleri gösterilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">h)</span>\n      <span class=\"clause-text text-muted\">Baca ağzı, bekleme barajları, kapalı barajlar, su ve taş tozu barajları, elektrik ve basınçlı hava ile çalışan cihazlar, ocak içi enerji hattı, hava yönleri, tali havalandırma hattı, hava kapıları, karakol, emici/üfleyici pervaneler, ana ve alternatif kaçış yönleri, yaşam hattı, acil toplanma yerleri, nakliyat (vinç, bant, konveyör, adi oluk), sensör grubu, su cebi, pasa alanı, stok alanı, ilkyardım odası, haberleşme (telefon/diafon/telsiz), yangın söndürücüler, hava ölçüm istasyonları, OFK istasyonları ilgili harita üzerinde gösterilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ı)</span>\n      <span class=\"clause-text text-muted\">Yer altı imalat haritalarındaki cevher ve kat isimlendirmesinde, çalışma bölgesindeki isimlendirme kullanılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">i)</span>\n      <span class=\"clause-text text-muted\">İmalat haritalarında; desandri, fere, başyukarı, baş aşağı gibi eğimli sürülen galerilerin eğim değerleri derece olarak eğim yönünde gösterilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">j)</span>\n      <span class=\"clause-text text-muted\">Yer altı açıklıklarında bulunan tüm kırık (kavşak, dönemeç) noktalarına, uzun ve düz açıklıklarda ise belirli aralıklarla taban kotları okunmalı ve haritada gösterilmelidir. Dikey açıklıklarda ise baş ve dip kotları ile birlikte bağlı oldukları kat isimleri de haritada gösterilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">k)</span>\n      <span class=\"clause-text text-muted\">Fiili olarak açık olan bölgeler düz çizgi, üretim planlanan bölgeler kesikli çizgi, desandri, başyukarı ve fereler noktalı kesik çizgi ile gösterilmelidir. Fiili olarak açık olan bölgeler ile projelendirilen açıklıkların üst üste gelmesi durumunda en üst kotta bulunan kısımlar düz çizgi, kesişim yerlerinde alt kotta kalan açıklıklar ise kesikli çizgi ile gösterilmelidir. Çok sayıda kesişim olması hâlinde ilgili bölge uygun doğrultuda kesit alınarak gösterilmelidir.</span>\n    </div><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> İHA sistemleri ile yapılan ölçümlerde uyulacak genel esaslar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-114\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 9- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 9- (1) Genel Müdürlüğe, Sayısal Fotogrametrik Harita üreten gerçek veya tüzel kişiler, SHGM tarafından yayımlanan İnsansız Hava Aracı Sistemleri Talimatında (SHT-İHA) belirtilen kurallara riayet etmekle yükümlüdürler.', 'MADDE 9- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Genel Müdürlüğe, Sayısal Fotogrametrik Harita üreten gerçek veya tüzel kişiler, SHGM tarafından yayımlanan İnsansız Hava Aracı Sistemleri Talimatında (SHT-İHA) belirtilen kurallara riayet etmekle yükümlüdürler.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Harita üretimi esnasında; askeri yasak bölgeler, askeri bina ve tesisler, cezaevi, akaryakıt depoları ve istasyonları, silah/fişek fabrika ve depoları gibi kritik tesis ve varlıkların bulunduğu alanlarda, yasa ve yönetmeliklerden kaynaklanan gizlilik kurallarına uyulmalıdır. Ayrıca kışla, bina ve tesislere ilişkin detaylar yer almamalı ve isimlendirme yapılmamalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) İHA kullanıcısının (harita mühendisi ya da harita teknikeri), asgari İHA 0 Ticari Pilot Sertifikası bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) Harita yapımında, asgari aşağıda belirtilen özellikleri haiz hava araçları kullanılmalıdır.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">Hava fotoğrafı çekiminde kullanılan kamera, sabit odak uzaklığına sahip olmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">Görüntü yürümesini engelleyecek yazılımsal ya da donanımsal çözümler bulunmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">Hava fotoğrafı çekiminde kullanılan kamera, balıkgözü tipi objektife sahip olmamalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">Hava fotoğrafı çekiminde en az 20 MP çözünürlüklü kamera kullanılmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">d)</span>\n      <span class=\"clause-text text-muted\">Hava fotoğrafı çekiminde, mümkün olduğunca RTK/PPK alıcı/anten kiti bulunan İHA sistemleri kullanılmalıdır.</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">(5) YKN ve BDN tesisinde aşağıda belirtilen standartlar sağlanmalıdır.</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">RTK/PPK özelliği bulunan İHA’lar ile uçuş yapılması hâlinde; uçuş planı yapılan alanda, uçuş planının her bir blok köşesi ve kırık noktasında en az 1 adet YKN tesis edilmeli ve bu YKN’ler arasındaki mesafe en fazla 1.000 m olmalıdır. Bununla birlikte uçuş planı yapılan alanın 50 hektar (dâhil)’dan daha küçük olması durumunda alanın yaklaşık orta noktasında en az 1 adet, 50 hektardan büyük olması durumunda ise homojen dağılımda en az 3 adet YKN tesis edilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">(a) bendinde belirtilen husus, RTK/PPK özelliği bulunan İHA’ların Fixed modda uçuş yapması ya da PPK yöntemi ile çözümleme yapılması hâlinde geçerlidir. Fixed modda uçuş yapılmaması veya PPK yöntemi ile çözümleme yapılmaması durumunda ise (c) bendinde belirlenen esaslara uyulmalıdır.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">RTK/PPK özelliği bulunmayan İHA’lar ile uçuş yapılması hâlinde; uçuş planı yapılan alanda, uçuş planının her bir blok köşesi ve kırık noktasında en az 1 adet, alan içerisinde de homojen dağılımda en az 3 adet YKN tesis edilmeli ve tesisi yapılan YKN’ler arası mesafe en fazla 250 m olmalıdır. Topoğrafyanın ani değişim gösterdiği (50 m veya daha fazla kot farkı olan) bölgelerde 250 m’lik yatay mesafe şartına bağlı kalmaksızın ilave YKN tesis edilmelidir.</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">(a), (b) ve (c) bentlerinde sayılan YKN tesisi şartlarını sağlamakla birlikte, uçuş planı yapılan alanın içerisinde ve homojen dağılımda en az 2 adet BDN tesis edilmeli ve BDN’ler tesis edilirken, proje sahasına homojen dağılmış olan YKN’lere mümkün olduğunca eşit mesafede olacak şekilde planlama yapılmalıdır.</span>\n    </div><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> YKN ve BDN tesisindeki hava işaretlerinin esasları</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-129\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 10- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 10- (1) Ağı oluşturan noktalar hava işaretleri şeklinde tesis edilmelidir.', 'MADDE 10- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Ağı oluşturan noktalar hava işaretleri şeklinde tesis edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Noktaların konum ve yükseklik doğrulukları bu Yönergede belirlenen standartlarda olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) Hava işaretleri, uçuş yüksekliği ve zemin rengine bağlı olarak (koyu zemin üzerine açık, açık zemin üzerine koyu renk) merkezdeki çapı 20 cm olan daire ya da 20x20 cm'lik kare, bu dairenin/karenin 20 cm uzağında, kanatların eni 20 cm boyu 40 cm olan dikdörtgen şekilde hazırlanmalıdır. Hava işareti tesisinde, merkezdeki daire ya da karenin etrafında en az iki kanat olacak şekilde tesis yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) Hava işaretleri, gökyüzü görüşü açık alanlara yapılmalı, işaretler en az 60°’lik bir görüş açısına sahip olmalı, bu görüş konisi içinde bina, ağaç gibi herhangi bir engel bulunmamalı, engel bulunması durumunda engel yüksekliğinin bir buçuk katı ötesine işaretleme yapılmalıdır.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Sayısal fotogrametrik harita ve ortofoto üretimindeki esaslar</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-134\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 11- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 11- (1) Hava fotoğraflarının yer örnekleme aralığı en fazla 7 cm olmalıdır.', 'MADDE 11- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Hava fotoğraflarının yer örnekleme aralığı en fazla 7 cm olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Boyuna bindirme oranı en az %80, enine bindirme oranı en az %60 olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) Sayısallaştırmada kullanılacak olan yoğun nokta bulutu çözünürlüğü çalışma sahasındaki detayları temsil edecek seviyede olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) (Değişik: 04/11/2025-2025530393) Ortofoto çözünürlüğü en fazla 7 cm, SYM çözünürlüğü en fazla 14 cm olmalı ve SYM üretiminde sadece nokta bulutu verisi kullanılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(5) BDN’lere gelen hataların karesel ortalaması, yatayda ve düşeyde en fazla 7 cm olmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(6) Görüntü alımlarının bulutsuz ve güneşli bir havada (gölge boyunun en azolduğu zaman aralığında) yapılması gerekmektedir. Alımı yapılacak alanda kar örtüsüolmamalıdır. Geniş yapraklı ağaçların çok yoğun olduğu alanlarda ise yaprakların oluşmadığıya da döküldüğü mevsimlerde alım yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(7) Detay ölçümünde kullanılacak stereo modellerde YÖA ölçütlerini sağlamayan hava fotoğrafları kullanılmamalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(8) Detay ölçümlerinde, arazi yüzeyinin, hava fotoğraflarından net bir şekilde tespit edilemediği durumlarda yersel bütünlemeye gidilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">Sayısal haritalar ve bu haritalar ile birlikte ibraz edilecek dosyalar</p></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-143\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 12- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 12- (1) Belirlenen esaslara göre üretilecek haritalarda, bu Yönerge ekinde yayımlanan tabaka yapısı, semboloji ve ölçü karneleri kullanılmalıdır.', 'MADDE 12- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Belirlenen esaslara göre üretilecek haritalarda, bu Yönerge ekinde yayımlanan tabaka yapısı, semboloji ve ölçü karneleri kullanılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(2) Sayısal harita, .dxf formatında ve dosyanın oluşturulduğu orijinal formatta ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(3) Projeksiyon ve datum dönüşümleri için bölgesel dönüşüm parametresi kullanılmalı ve kullanılan dönüşüm parametresi, 26.6.2018 tarihli ve 30460 sayılı Resmî Gazete’de yayımlanan Büyük Ölçekli Harita ve Harita Bilgileri Üretim Yönetmeliğinin 79 uncu maddesinin birinci fıkrasının (d) bendinde belirtilen esaslara uygun olmalıdır. GNSS cihazlarına yüklenecek yazılımlar ile veya doğrudan dönüşüm yapan programlar aracılığı ile projeksiyon ve datum dönüşümü yapılmamalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">(4) Ölçüm işleminin elektronik uzunluk ölçerler ile yapılması durumunda, ölçüme ait ham data verisi veya iş dosyası ile YDE veya YMK dosyası ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(5) TUSAGA-Aktif/GNSS veya RTK/GNSS yöntemlerinden herhangi birisi ile sabit nokta tesis edilmesi veya alım yapılması durumunda; tesis edilen nokta veya alım yapılan noktalara ait verileri içerir ham data dosyası (.rw5, .raw, .mjf vb. formatlar) ile TKGM formatındaki excel dosyası ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(6) Teodolit veya pusula ölçü karnesini oluşturan değerler bu Yönerge ekinde yayımlanan formatta doldurularak ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">(7) İHA sistemleri ile harita ve harita bilgilerinin üretilmesi hâlinde;</p><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">a)</span>\n      <span class=\"clause-text text-muted\">Dengelenmiş dış yöneltme parametreleri,</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">b)</span>\n      <span class=\"clause-text text-muted\">Sayısal Yüzey Modeli (SYM), (.tif formatında),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">c)</span>\n      <span class=\"clause-text text-muted\">Nokta Bulutu (.las veya .laz formatında),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">ç)</span>\n      <span class=\"clause-text text-muted\">YKN ve BDN’lere ait; ham data dosyası, koordinat ve kot özet çizelgesi (.txt, excel vb.),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">d)</span>\n      <span class=\"clause-text text-muted\">Dengeleme Raporu (YÖA, YKN ve BDN’lere ait bilgiler, kamera kalibrasyon bilgileri gibi uçuşa ait bilgiler),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">e)</span>\n      <span class=\"clause-text text-muted\">Sayısal ortofoto görüntüler (.tif ve .ecw formatları ile .kml ya da .kmz formatındaki veri),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">f)</span>\n      <span class=\"clause-text text-muted\">PPK veri işleme raporu ve düzeltilmiş fotoğraf orta nokta koordinatlarına ait text dosyası (PPK yöntemi ile çözümleme yapılması durumunda),</span>\n    </div><div class=\"legislation-clause-item\">\n      <span class=\"clause-letter font-mono font-bold text-cyan\">g)</span>\n      <span class=\"clause-text text-muted\">İHA kullanıcısının ticari pilot sertifikası,</span>\n    </div><p class=\"legislation-p leading-relaxed text-muted\">ibraz edilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">Dosya tesliminde kullanılacak klasör yapısı ve içerikleri</p></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-160\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 13- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 13- (1) Genel Müdürlüğe ibraz edilecek harita ve diğer verilere ait klasör yapısı aşağıda belirlenen standartlarda olmalıdır.', 'MADDE 13- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Genel Müdürlüğe ibraz edilecek harita ve diğer verilere ait klasör yapısı aşağıda belirlenen standartlarda olmalıdır.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> a) Yersel ölçüm yöntemi ile üretilen haritalar için;</h3><p class=\"legislation-p leading-relaxed text-muted\">1_CIZIM: “1_CIZIM” adlı klasör içerisinde, aşağıda örneklendirildiği şekilde isimlendirilmiş, TM Projeksiyon ITRF 96 Datum (3 derecelik) ve UTM Projeksiyon ED 50 Datum (6 derecelik) sistemlerinde hazırlanmış sayısal haritalar bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">Aynı ölçüm bölgesine ait birden fazla dosya ibraz edilen alanlarda klasör isimlendirmesi 1, 2, 3… olarak sıralı şekilde oluşturulmalıdır. Sicil numarası olan sahalar için sicil numarası, sicil numarası olmayan sahalar için erişim numarası ile isimlendirme yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">438721527940999909828_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">Total Station/Elektronik Uzunluk Ölçer ile ölçüm yapılmış ise;</p><p class=\"legislation-p leading-relaxed text-muted\">2_TS_HAM_DATA: “2_TS_HAM_DATA” adlı klasör içerisinde, ölçüm yapılan cihazın marka ve modeli metin belgesi (text dosyası) içerisinde belirtilmelidir.</p><p class=\"legislation-p leading-relaxed text-muted\">Ölçüme ait ham data verisi veya iş dosyası ile YDE veya YMK dosyası (kullanılan cihazın, marka ve modeline göre oluşturduğu ham data dosya formatı) klasör içeriğinde Sicil/Erişim No_tstation isimlendirmesi şeklinde bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">Birden fazla aynı tip cihaz kullanılması durumunda isimlendirme, Sicil/Erişim No_tstation_1, 2, 3… şeklinde sıralı olarak yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">77679873715topcon_gpt7500.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_tstation.gts7 (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.yde_20052680.ymk (YDE/YMK)</p><p class=\"legislation-p leading-relaxed text-muted\">topcon_gpt7500.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_tstation.gts7 (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.yde_20052680.ymk (YDE/YMK)</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">Teodolit veya pusula ile ölçüm yapılmış ise;</p><p class=\"legislation-p leading-relaxed text-muted\">3_OLCU_KARNESI: “3_OLCU_KARNESI” adlı klasör içerisinde, Teodolit veya pusula ile ölçüm yapılması hâlinde, bu Yönerge ekinde yayımlanan şablona uygun şekilde düzenlenmiş ölçü karnesi bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">7774337327420052680_teodolit.xls (teodolit ölçü karnesi)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_pusula.xls (pusula ölçü karnesi)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_teodolit.xls (teodolit ölçü karnesi)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_pusula.xls (pusula ölçü karnesi)</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">GNSS/RTK ile ölçüm yapılmış ise;</p><p class=\"legislation-p leading-relaxed text-muted\">4_GNSS_HAM_DATA: “4_GNSS_HAM_DATA” adlı klasör içerisinde, ölçüm yapılan cihazın marka ve modeli metin belgesi (text dosyası) içerisinde belirtilmelidir. Ölçüme ait ham data verisi ve ham data verisinden oluşturulan excel formatındaki dosya ile text formatındaki (bu Yönergeye uygun olarak tesis edilen ve projede kullanılan (kesin) poligon değerleri bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">Birden fazla aynı tip cihaz kullanılması durumunda isimlendirme Sicil/Erişim No_gps_1, 2, 3… şeklinde sıralı olarak yapılmalıdır. Nirengi veya pilyeden çıkış alınması durumunda, oluşturulan bir text dosyası içerisinde bu husus belirtilmelidir. Söz konusu nirengi/pilyeye ait ITRF 96 Datum (3 derecelik) koordinat değerleri bilinmiyorsa ED 50 Datum (3 derecelik) veya ED 50 Datum (6 derecelik) sistemlerdeki koordinat değerleri ile birlikte nirengi/pilyeden bu Yönergede belirlenen standartlarına göre okunan ITRF 96 Datum (3 derecelik) sistemdeki koordinat değerleri de .pdf formatında bu klasör içerisinde bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">77978080010topcon_hipersr.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_gps.mjf (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_xls (TKGM formatında oluşturulmuş excel dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (kesin poligon değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">topcon_hipersr.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_gps.mjf (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_xls (TKGM formatında oluşturulmuş excel dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (kesin poligon değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">5_DONUSUM_PARAMETRESI: “5_DONUSUM_PARAMETRESI” adlı klasör içerisinde, ITRF 96 Datum (3 derecelik) sistemden ED 50 Datum (3 derecelik) sisteme veya ED 50 Datum (3 derecelik) sistemden ITRF 96 Datum (3 derecelik) sisteme dönüşüm için kullanılan .dns formatındaki bölgesel dönüşüm parametresi bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">88055264328bala_itrf_ed50.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_ed50_itrf.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_itrf_ed50.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_ed50_itrf.dns</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">6_HESAP: “6_HESAP” adlı klasör içerisinde, YDE veya YMK dosyası, kesin poligon hesabı text dosyası, poligon okuma değerleri, geriden kestirme hesabı ve ayrıca geriden kestirme yapılarak koordinatı belirlenen istasyon noktasına ait koordinat ve kot bilgilerini içeren text dosyası bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">7612274204820052680_tstation.yde</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_tstation.ymk</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (kesin poligon değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_tstation.yde</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_tstation.ymk</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (kesin poligon değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> b) İHA sistemleri ile üretilen haritalar için;</h3><p class=\"legislation-p leading-relaxed text-muted\">1_CIZIM: “1_CIZIM” adlı klasör içerisinde, aşağıda örneklendirildiği şekilde isimlendirilmiş, TM Projeksiyon ITRF 96 Datum (3 derecelik) ve UTM Projeksiyon ED 50 Datum (6 derecelik) sistemlerinde hazırlanmış sayısal haritalar bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">Aynı ölçüm bölgesine ait birden fazla dosya ibraz edilen alanlarda klasör isimlendirmesi 1, 2, 3… olarak sıralı şekilde oluşturulmalıdır. Sicil numarası olan sahalar için Sicil Numarası, Sicil numarası olmayan sahalar için Erişim Numarası ile isimlendirme yapılmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">41027357620999909828_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">999909828_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">3062556_imalat_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_ed50_6.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.dxf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_halihazir_itrf_3.ncz</p><p class=\"legislation-p leading-relaxed text-muted\">2_DIS_YONELTME: “2_DIS_YONELTME” adlı klasör içerinde .txt formatındaki dış yöneltme parametrelerini içeren dosya bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_dis_yoneltme.txt</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_dis_yoneltme.txt</p><p class=\"legislation-p leading-relaxed text-muted\">3_SYM: “3_SYM” adlı klasör içerisinde .tif formatındaki sayısal yüzey modeli dosyası bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_sym.tif</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_sym.tif</p><p class=\"legislation-p leading-relaxed text-muted\">4_NOKTA_BULUTU: “4_NOKTA_BULUTU” adlı klasör içerisinde .las veya .laz formatındaki nokta bulutu dosyası bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">45339027178020052680_nokta_bulutu.las</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_nokta_bulutu.laz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_nokta_bulutu.las</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_nokta_bulutu.laz</p><p class=\"legislation-p leading-relaxed text-muted\">5_YKN_BDN: “5_YKN_BDN” adlı klasör içerisinde; poligon, YKN ve BDN noktalarının tesisinde kullanılan cihazın marka ve modeli, metin belgesi (text dosyası) içerisinde belirtilmelidir. Nokta tesisine ait ham data verisi ve ham data verisinden elde edilen TKGM formatındaki dosya, klasör içeriğinde bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">topcon_hipersr.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_gps.mjf (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_xls (TKGM formatında oluşturulmuş excel dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (YKN ve BDN kesin değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">topcon_hipersr.txt (cihazın marka ve modeli)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_gps.mjf (ham data dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_xls (TKGM formatında oluşturulmuş excel dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_kesinpol.txt (YKN ve BDN kesin değerlerine ait txt dosyası)</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">6_DENGELEME_RAPORU: “6_DENGELEME_RAPORU” adlı klasör içerisinde yapılan dengeleme işlemine ait .pdf formatındaki dosya bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">8553458255020052680_dengeleme.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_dengeleme.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">7_DONUSUM_PARAMETRESI: “7_DONUSUM_PARAMETRESI” adlı klasör içerisinde, ITRF 96 Datum (3 derecelik) sistemden ED 50 Datum (3 derecelik) sisteme veya ED 50 Datum (3 derecelik) sistemden ITRF 96 Datum (3 derecelik) sisteme dönüşüm için kullanılan .dns formatındaki bölgesel dönüşüm parametresi bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">88759274185bala_itrf_ed50.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_ed50_itrf.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_itrf_ed50.dns</p><p class=\"legislation-p leading-relaxed text-muted\">bala_ed50_itrf.dns</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">8_ORTOFOTO: “8_ORTOFOTO” adlı klasör içerisinde .tif ve .ecw formatlarındaki dosyalar ile .kml ya da .kmz formatındaki dosyalardan birisi bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">8817945455520052680_ortofoto.tif</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_ortofoto.ecw</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.kml</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.kmz</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_ortofoto.tif</p><p class=\"legislation-p leading-relaxed text-muted\">20052680_ortofoto.ecw</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.kml</p><p class=\"legislation-p leading-relaxed text-muted\">20052680.kmz</p><p class=\"legislation-p leading-relaxed text-muted\">3266109100330</p><p class=\"legislation-p leading-relaxed text-muted\">9_VERI_ISLEME_RAPORU:“9_VERI_ISLEME_RAPORU” adlı klasör içerisinde PPK yöntemi ile çözümleme yapılması durumunda oluşan .txt, .xlsx, .pdf vb. formattaki rapor ile düzeltilmiş fotoğraf orta nokta koordinatlarına ait text dosyası bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">veri_isleme.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">veri_isleme.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><p class=\"legislation-p leading-relaxed text-muted\">10_SERTİFİKA: “10_SERTIFIKA” adlı klasör içerisinde İHA kullanıcısının İHA 0 Ticari Pilot Sertifikasının bir örneği bulunmalıdır.</p><p class=\"legislation-p leading-relaxed text-muted\">sertifika.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">sertifika.pdf</p><p class=\"legislation-p leading-relaxed text-muted\">Örn:</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Yürürlük</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-310\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 14- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 14- (1) Bu Yönerge 1/5/2025 tarihinden itibaren geçerli olmak üzere Genel Müdür tarafından onaylandığı tarihte yürürlüğe girer.', 'MADDE 14- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönerge 1/5/2025 tarihinden itibaren geçerli olmak üzere Genel Müdür tarafından onaylandığı tarihte yürürlüğe girer.</p><h3 class=\"legislation-section-title\"><i class=\"fa-solid fa-bookmark text-amber\"></i> Yürütme</h3></div></div><div class=\"legislation-article-card\" id=\"mapeg-art-312\">\n        <div class=\"legislation-article-head\">\n          <span class=\"legislation-art-badge\">MADDE 15- (1)</span>\n          <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('MADDE 15- (1) Bu Yönerge hükümlerini Maden ve Petrol İşleri Genel Müdürü yürütür.', 'MADDE 15- (1)')\" title=\"Maddeyi Kopyala\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n        </div>\n        <div class=\"legislation-article-content\">\n          <p class=\"legislation-p leading-relaxed font-semibold text-white\">Bu Yönerge hükümlerini Maden ve Petrol İşleri Genel Müdürü yürütür.</p><p class=\"legislation-p leading-relaxed text-muted\">Ekler:</p><p class=\"legislation-p leading-relaxed text-muted\">Yönergenin Yürürlüğe Konulduğu Genel Müdür Olurunun</p><p class=\"legislation-p leading-relaxed text-muted\">Tarihi</p><p class=\"legislation-p leading-relaxed text-muted\">Sayısı</p><p class=\"legislation-p leading-relaxed text-muted\">26/03/2025</p><p class=\"legislation-p leading-relaxed text-muted\">2025150415</p><p class=\"legislation-p leading-relaxed text-muted\">Yönergede Değişiklik Yapan Yönergelerin Genel Müdür Olurlarının</p><p class=\"legislation-p leading-relaxed text-muted\">Tarihi</p><p class=\"legislation-p leading-relaxed text-muted\">Sayısı</p><p class=\"legislation-p leading-relaxed text-muted\">1.</p><p class=\"legislation-p leading-relaxed text-muted\">04/11/2025</p><p class=\"legislation-p leading-relaxed text-muted\">2025530393</p></div></div></div></div>",
  "bohhbuy": "<div class=\"legislation-doc-container\">\n  <div class=\"legislation-doc-header\">\n    <div class=\"d-flex items-center gap-6 mb-2\">\n      <span class=\"badge badge-emerald font-mono\">T.C. CUMHURBAŞKANLIĞI</span>\n      <span class=\"badge badge-cyan font-mono\">R.G. 26.06.2018 / 30460 (MÜKERRER)</span>\n    </div>\n    <h2 class=\"legislation-doc-title\">BÜYÜK ÖLÇEKLİ HARİTA VE HARİTA BİLGİLERİ ÜRETİM YÖNETMELİĞİ (BÖHHBÜY)</h2>\n    <div class=\"legislation-meta-bar\">\n      <span><i class=\"fa-solid fa-scale-balanced text-emerald\"></i> Karar Sayısı: 2018/11962</span>\n      <span><i class=\"fa-solid fa-clock-rotate-left text-amber\"></i> Son Güncelleme: 04.10.2025 (R.G. 33037)</span>\n    </div>\n  </div>\n  <div class=\"legislation-doc-body\">\n    <div class=\"legislation-article-card\">\n      <div class=\"legislation-article-head\">\n        <span class=\"legislation-art-badge\">MADDE 1 - Amaç ve Kapsam</span>\n      </div>\n      <div class=\"legislation-article-content\">\n        <p class=\"legislation-p leading-relaxed text-white\">Bu Yönetmeliğin amacı; büyük ölçekli mekânsal bilgilerin ve haritaların üretiminde standardizasyonu sağlamak, coğrafi bilgi sistemlerine altlık teşkil edecek temel jeodezik ağlar ile sayısal harita bilgilerinin üretim teknik ve doğruluk esaslarını belirlemektir.</p>\n      </div>\n    </div>\n\n    <div class=\"legislation-article-card\">\n      <div class=\"legislation-article-head\">\n        <span class=\"legislation-art-badge\">MADDE 28 - TUSAGA-Aktif (CORS-TR) ve RTK Ölçüleri</span>\n        <button type=\"button\" class=\"legislation-copy-clause-btn\" onclick=\"window.copyLegislationClause('BÖHHBÜY Madde 28 uyarınca yapılan TUSAGA-Aktif (CORS-TR) çift okuma RTK ölçülerinde konum farkı (dS) <= 7 cm ve kot farkı (dH) <= 10 cm yasal tolerans limitleri içindedir.', 'BÖHHBÜY Madde 28')\"><i class=\"fa-solid fa-copy\"></i> Kopyala</button>\n      </div>\n      <div class=\"legislation-article-content\">\n        <p class=\"legislation-p leading-relaxed text-white\">TUSAGA-Aktif sistemi ile gerçek zamanlı kinematik (RTK) veya post-process (PPK) yöntemiyle yapılacak detay ve parsel köşe noktası ölçümlerinde aşağıdaki kurallara uyulur:</p>\n        <div class=\"legislation-clause-item\"><span class=\"clause-letter font-mono font-bold text-cyan\">a)</span><span class=\"clause-text text-muted\">Ölçüler en az 10 epok ortalaması alınarak kaydedilir. PDOP değeri 4'ten küçük olmalıdır.</span></div>\n        <div class=\"legislation-clause-item\"><span class=\"clause-letter font-mono font-bold text-cyan\">b)</span><span class=\"clause-text text-muted\"><strong>Çift Okuma Kriteri:</strong> Her nokta en az 60 dakika (1 saat) zaman farkıyla iki bağımsız oturumda ölçülmelidir.</span></div>\n        <div class=\"legislation-clause-item\"><span class=\"clause-letter font-mono font-bold text-cyan\">c)</span><span class=\"clause-text text-muted\"><strong>Yasal Hata Sınırları:</strong> İki okuma arasındaki yatay konum farkı <strong>ΔS ≤ 7 cm</strong>, düşey yükseklik farkı <strong>ΔH ≤ 10 cm</strong> olmalıdır.</span></div>\n      </div>\n    </div>\n\n    <div class=\"legislation-article-card\">\n      <div class=\"legislation-article-head\">\n        <span class=\"legislation-art-badge\">MADDE 24 - C3 Poligon Noktası Hata Sınırları</span>\n      </div>\n      <div class=\"legislation-article-content\">\n        <p class=\"legislation-p leading-relaxed text-white\">C3 derece poligon noktalarının GNSS ile belirlenmesinde:</p>\n        <div class=\"legislation-clause-item\"><span class=\"clause-letter font-mono font-bold text-cyan\">a)</span><span class=\"clause-text text-muted\">Farklı uydu konfigürasyonlarında en az 2 saat (120 dk) arayla iki bağımsız ölçü yapılır.</span></div>\n        <div class=\"legislation-clause-item\"><span class=\"clause-letter font-mono font-bold text-cyan\">b)</span><span class=\"clause-text text-muted\">Konum farkı <strong>ΔS ≤ 3 cm</strong>, elipsoit kot farkı <strong>Δh ≤ 5 cm</strong> olmalıdır.</span></div>\n      </div>\n    </div>\n\n    <div class=\"legislation-article-card\">\n      <div class=\"legislation-article-head\">\n        <span class=\"legislation-art-badge\">MADDE 31 - Geometrik Nivelman Kriterleri</span>\n      </div>\n      <div class=\"legislation-article-content\">\n        <p class=\"legislation-p leading-relaxed text-white\">Geometrik nivelman hatlarında gidiş ve dönüş nivelmanı arasındaki kapanma hatası <strong>Δh ≤ 12 mm √S (km)</strong> bağıntısını sağlamak zorundadır.</p>\n      </div>\n    </div>\n  </div>\n</div>"
};
